package com.aicharacter.v3;
/** God observes durable events. A message can never exist without a source world-event id. */
public final class GodAttentionEngine{private GodAttentionEngine(){}
 public static void consume(WorldState s,WorldHistoryEntry e){if(!WorldEventBus.has(s,e.eventId)){s.lastGodTrace="event="+e.eventId+" relevance=REJECTED reason=source event not durable";return;}String priority=null,text=null,reason=null,girl=DisplayNames.girl(s);switch(e.type){case"GIRL_STARTED_SEARCH":priority="IMPORTANT";reason="girl searching for player-cat";text=girl+" đang tìm bạn…";break;case"GIRL_FOUND_CAT":priority="IMPORTANT";reason="girl found player-cat by local perception";text=girl+" đã tìm thấy bạn.";break;case"GIRL_CALLING_CAT_TO_WAKE":priority="NOTICE";reason="girl chose to call sleeping player-cat";text=girl+" đang gọi bạn dậy.";break;case"CAT_WEATHER_RISK":priority="ALERT";reason="weather risk directly affects player-cat";text="Thời tiết nơi bạn đang nghỉ đang xấu đi.";break;case"CAT_ATTACHED_TO_GIRL":priority="NOTICE";reason="unusual carried sleep context";text="Bạn đã ngủ trong một chỗ an toàn mà "+girl+" đang mang theo.";break;default:s.lastGodTrace="event="+e.eventId+" type="+e.type+" relevance=NO reason=normal/non-player-critical";return;}String mid="god_"+e.eventId;for(GodMessage m:s.godInbox)if(m.messageId.equals(mid))return;GodMessage m=new GodMessage(mid,e.eventId,priority,text,e.time);s.godInbox.add(m);while(s.godInbox.size()>40)s.godInbox.remove(0);s.lastGodTrace="event="+e.eventId+" type="+e.type+" relevance=YES reason="+reason+" message="+mid+" notification=pending";}
 public static GodMessage nextDelivery(WorldState s){for(GodMessage m:s.godInbox)if(!m.delivered)return m;return null;}
 public static boolean grounded(WorldState s,GodMessage m){for(WorldHistoryEntry e:s.worldHistory)if(e.eventId.equals(m.sourceEventId))return true;return false;}
}
